CREATE TABLE orchestration_commands (id TEXT PRIMARY KEY, type TEXT NOT NULL, aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('task', 'version')), aggregate_id TEXT NOT NULL, expected_version INTEGER NOT NULL CHECK (expected_version > 0), actor_id TEXT NOT NULL, issued_at TEXT NOT NULL, reason TEXT NOT NULL, parameters TEXT NOT NULL CHECK (json_valid(parameters)), status TEXT NOT NULL CHECK (status IN ('pending', 'executing', 'succeeded', 'failed', 'rejected', 'unknown', 'needs_human')), result TEXT CHECK (result IS NULL OR json_valid(result)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE orchestration_events (id TEXT PRIMARY KEY, sequence INTEGER NOT NULL CHECK (sequence > 0), aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('task', 'version')), aggregate_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL CHECK (aggregate_version > 0), type TEXT NOT NULL, command_id TEXT NOT NULL, actor_id TEXT NOT NULL, occurred_at TEXT NOT NULL, data TEXT NOT NULL CHECK (json_valid(data)), previous_hash TEXT, hash TEXT NOT NULL UNIQUE, UNIQUE (aggregate_type, aggregate_id, aggregate_version));
CREATE INDEX idx_orchestration_events_head ON orchestration_events (aggregate_type, aggregate_id, sequence);
CREATE TABLE orchestration_aggregates (aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('task', 'version')), aggregate_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL CHECK (aggregate_version >= 0), state TEXT NOT NULL, snapshot TEXT CHECK (snapshot IS NULL OR json_valid(snapshot)), updated_at TEXT NOT NULL, PRIMARY KEY (aggregate_type, aggregate_id));
CREATE TABLE orchestration_external_refs (source TEXT NOT NULL, external_id TEXT NOT NULL, aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('task', 'version')), aggregate_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (source, external_id));
CREATE TABLE orchestration_approvals (id TEXT PRIMARY KEY, command_id TEXT, object_type TEXT NOT NULL CHECK (object_type IN ('task', 'version')), object_id TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT, parameters TEXT NOT NULL CHECK (json_valid(parameters)), status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'expired')), created_at TEXT NOT NULL, decided_at TEXT);
CREATE TABLE orchestration_leases (id TEXT PRIMARY KEY, aggregate_type TEXT NOT NULL CHECK (aggregate_type IN ('task', 'version')), aggregate_id TEXT NOT NULL, holder TEXT NOT NULL, fencing_token INTEGER NOT NULL CHECK (fencing_token >= 0), expires_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE (aggregate_type, aggregate_id));
